<?php
declare(strict_types=1);require_once __DIR__.'/../src/auth.php';require_once __DIR__.'/../src/permissions.php';$u=auth_require_login();require_role('ADMIN');$id=filter_input(INPUT_GET,'accounting_entry_id',FILTER_VALIDATE_INT)?:0;?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manuelle VF-Synchronisation</title><link rel="stylesheet" href="app.css"><style>.required{color:#b91c1c;font-weight:700}pre{white-space:pre-wrap}.choice{padding:1rem;border:1px solid #ddd;margin:.75rem 0}</style></head><body><h1>Manuelle VF-Synchronisation</h1><p class="info">Diese Maske ruft keine VF-REST-Schnittstelle auf. Sie dokumentiert eine bereits manuell in VF durchgeführte Korrektur.</p><div class="card"><label>LSZJ-ID <span class="required">* Pflichtfeld</span><input id="entryId" type="number" min="1" value="<?=$id?>"></label><button id="load">Vorschau laden</button></div><div id="out"></div><script>'use strict';const csrf=<?=json_encode(csrf_token())?>;let view=null;const $=i=>document.getElementById(i),e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));async function api(b){const r=await fetch('api_vf_manual_sync.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...b,csrf_token:csrf})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Fehler');return d.result}async function preview(){try{view=await api({action:'preview',accounting_entry_id:+$('entryId').value});out.innerHTML=`<div class="card"><h2>Vorschau</h2><p>Ursprüngliche VF-flid: <strong>${e(view.vf_flid)}</strong><br>Zeilenversion: ${e(view.row_version)}<br>D1-Grund: ${e(view.change_reason)}<br>REST-Aufrufe: 0</p><details open><summary>Unterschiede</summary><pre>${e(JSON.stringify(view.differences,null,2))}</pre></details><label>Art <span class="required">* Pflichtfeld</span><select id="kind"><option value="manual_edit">Bestehenden, nicht abgerechneten VF-Flug manuell korrigiert</option><option value="billing_replacement">Abgerechneten VF-Flug storniert und manuell ersetzt</option></select></label><label>Aktive VF-flid <span class="required">* Pflichtfeld</span><input id="flid" type="number" min="1" value="${e(view.vf_flid)}"></label><label>Korrekturgrund <span class="required">* Pflichtfeld</span><textarea id="reason" minlength="5" maxlength="1000" required></textarea></label><label>Notizen<textarea id="notes" maxlength="1000"></textarea></label><div class="choice"><label><input id="checked" type="checkbox"> Ich habe die konkrete VF-flid und den korrigierten Flug unmittelbar in VF geprüft. <span class="required">* Pflichtfeld</span></label></div><div class="choice"><label><input id="confirmed" type="checkbox"> Ich bestätige, dass der angezeigte LSZJ-Payload dem aktiven VF-Flug entspricht. <span class="required">* Pflichtfeld</span></label></div><button id="complete">Manuelle Synchronisation abschliessen</button></div>`;$('kind').onchange=()=>{$('flid').value=$('kind').value==='manual_edit'?view.vf_flid:''};$('complete').onclick=finish}catch(x){out.innerHTML='<div class="warnbox">'+e(x.message)+'</div>'}}async function finish(){if($('reason').value.trim().length<5||!$('checked').checked||!$('confirmed').checked||+$('flid').value<=0){alert('Pflichtfelder fehlen.');return}if(!confirm('Manuelle VF-Synchronisation revisionssicher abschliessen?'))return;try{const r=await api({action:'complete',accounting_entry_id:view.accounting_entry_id,expected_row_version:view.row_version,expected_payload_hash:view.current_payload_hash,sync_kind:$('kind').value,active_vf_flid:+$('flid').value,reason:$('reason').value.trim(),notes:$('notes').value.trim(),vf_checked:true,confirmed:true});out.innerHTML=`<div class="okbox">Abgeschlossen. Lauf ${e(r.manual_sync_run_id)}, Snapshot ${e(r.snapshot_id)}, aktive VF-flid ${e(r.active_vf_flid)}. REST-Aufrufe: 0.</div>`}catch(x){out.innerHTML='<div class="warnbox">'+e(x.message)+'</div>'}}$('load').onclick=preview;if(+$('entryId').value>0)preview();</script></body></html>
